const PROFILES={low:[.08,.08,.08,.08],medium:[.20,.20,.20,.20],heavy:[.34,.34,.34,.34],unbalanced:[.36,.36,.09,.09]};
const makeNode=()=>({queues:[0,0,0,0],phase:0,age:0,yellow:0,pending:null,fixedAge:0,pedestrians:2,bicycles:1});
const state={scenario:'medium',topology:'grid',controller:'dqn',speed:5,running:true,t:0,nodes:[0,1,2,3].map(makeNode),arrived:0,processed:0,delay:0,switches:0,turns:{left:0,right:0},history:[],events:[],lastQueue:0};
const $=id=>document.getElementById(id),dirs=['north','south','east','west'];
function poisson(lambda){let L=Math.exp(-lambda),p=1,k=0;do{k++;p*=Math.random()}while(p>L);return k-1}
function rates(){if(state.scenario!=='rush')return PROFILES[state.scenario];const p=(state.t%1200)/1200;if(p<.25)return PROFILES.low;if(p<7/12)return [.38,.38,.10,.10];if(p<5/6)return [.10,.10,.38,.38];return PROFILES.medium}
function activeNodes(){return state.topology==='single'?[state.nodes[0]]:state.nodes}
function chooseAction(node){const ns=node.queues[0]+node.queues[1],ew=node.queues[2]+node.queues[3];if(node.yellow)return 0;if(state.controller==='random')return Math.floor(Math.random()*3);if(state.controller==='fixed'){node.fixedAge++;if(node.fixedAge>=30){node.fixedAge=0;return node.phase===0?2:1}return 0}if(node.age<5)return 0;const current=node.phase===0?ns:ew,opposing=node.phase===0?ew:ns;if(state.controller==='heuristic')return opposing>current*1.2&&opposing>0?(node.phase===0?2:1):0;const network=activeNodes().reduce((s,n)=>s+n.queues.reduce((a,b)=>a+b,0),0);const vulnerable=node.pedestrians+node.bicycles;const pressure=opposing-current+network/Math.max(12,activeNodes().length*12)+vulnerable*.18;return pressure>3.2||node.age>55?(node.phase===0?2:1):0}
function log(message){state.events.unshift({t:state.t,message});state.events=state.events.slice(0,4)}
function boundaryArrivals(){const profile=rates();if(state.topology==='single'){profile.map(poisson).forEach((v,i)=>{state.nodes[0].queues[i]=Math.min(100,state.nodes[0].queues[i]+v);state.arrived+=v});return}const boundaries=[[0,0],[1,0],[2,1],[3,1],[0,3],[2,3],[1,2],[3,2]];boundaries.forEach(([n,a])=>{const v=poisson(profile[a]);state.nodes[n].queues[a]=Math.min(100,state.nodes[n].queues[a]+v);state.arrived+=v})}
function downstream(nodeIndex,approach){const row=Math.floor(nodeIndex/2),col=nodeIndex%2;const target=approach===0?[row+1,col,0]:approach===1?[row-1,col,1]:approach===2?[row,col-1,2]:[row,col+1,3];return target[0]>=0&&target[0]<2&&target[1]>=0&&target[1]<2?[target[0]*2+target[1],target[2]]:null}
function signalPhase(){const cycle=state.t%30;if(cycle<11)return'horizontal';if(cycle<12)return'clearance';if(cycle<23)return'vertical';if(cycle<24)return'clearance';if(cycle<28)return'pedestrian';return'clearance'}
function pedestrianPhase(){return signalPhase()==='pedestrian'}
function step(){boundaryArrivals();const transfers=[];activeNodes().forEach((node,nodeIndex)=>{node.pedestrians=Math.min(24,node.pedestrians+poisson(.09));node.bicycles=Math.min(18,node.bicycles+poisson(.07));const action=chooseAction(node);if(!node.yellow&&action&&action-1!==node.phase&&node.age>=5){node.pending=action-1;node.yellow=3;state.switches++;if(state.t%8===0)log(`Agent ${'ABCD'[nodeIndex]} requested ${node.pending===0?'NS':'EW'} green`)}state.delay+=node.queues.reduce((a,b)=>a+b,0)+node.pedestrians+node.bicycles;if(node.yellow){node.yellow--;if(!node.yellow){node.phase=node.pending;node.pending=null;node.age=0}return}const safePhase=signalPhase();if(safePhase==='pedestrian'){node.pedestrians=Math.max(0,node.pedestrians-1);node.age++;return}if(safePhase==='clearance'){node.age++;return}const active=safePhase==='vertical'?[0,1]:[2,3];active.forEach(approach=>{if(node.queues[approach]&&Math.random()<.8){node.queues[approach]--;const movement=Math.random();if(movement<.15){state.turns.left++;state.processed++}else if(movement<.25){state.turns.right++;state.processed++}else if(state.topology!=='single'){const next=downstream(nodeIndex,approach);next?transfers.push(next):state.processed++}else state.processed++}});if(node.age>0&&node.age%6===0)node.bicycles=Math.max(0,node.bicycles-1);node.age++});transfers.forEach(([n,a])=>{state.nodes[n].queues[a]=Math.min(100,state.nodes[n].queues[a]+1)});state.t++;const aggregate=activeNodes().reduce((sum,node)=>[sum[0]+node.queues[0]+node.queues[1],sum[1]+node.queues[2]+node.queues[3]],[0,0]);state.history.push(aggregate);if(state.history.length>120)state.history.shift();if(state.t%60===0)log(`Minute ${Math.floor(state.t/60)} · ${state.processed} completed trips`);if(state.t>=1200)reset(false)}
function reset(announce=true){state.nodes=[0,1,2,3].map(makeNode);Object.assign(state,{t:0,arrived:0,processed:0,delay:0,switches:0,turns:{left:0,right:0},history:[],events:[],lastQueue:0});if(announce)log('Network reset · new stochastic demand');render()}
function cars(el,count){el.innerHTML=Array.from({length:Math.min(count,12)},(_,i)=>`<span class="car ${i<2?'hot':''}"></span>`).join('')}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function drawChart(){const canvas=$('queueChart'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=18;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#232c35';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=pad+(h-pad*2)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke()}const max=Math.max(12,...state.history.flat());[['#26e6a4',0],['#43c6e8',1]].forEach(([color,index])=>{ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();state.history.forEach((v,i)=>{const x=pad+(w-pad*2)*i/119,y=h-pad-v[index]/max*(h-pad*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
function renderSingle(){const node=state.nodes[0],inter=$('intersection'),phase=signalPhase();inter.className=`intersection ${phase==='pedestrian'?'ped-crossing':phase==='clearance'?'all-red':phase==='horizontal'?'ew-green':'ns-green'}`;dirs.forEach((d,i)=>{$(`${d}Queue`).textContent=node.queues[i];cars(document.querySelector(`.queue-${d[0]}`),node.queues[i])})}
function renderGrid(){const phase=signalPhase(),walking=phase==='pedestrian',clearance=phase==='clearance',grid=$('networkGrid');grid.classList.toggle('flow-horizontal',phase==='horizontal');grid.classList.toggle('flow-vertical',phase==='vertical');grid.classList.toggle('ped-crossing',walking);grid.classList.toggle('all-red',clearance);document.querySelectorAll('.grid-node').forEach((el,i)=>{const node=state.nodes[i],total=node.queues.reduce((a,b)=>a+b,0);el.classList.toggle('yellow',!!node.yellow);el.classList.toggle('active',total===Math.max(...state.nodes.map(n=>n.queues.reduce((a,b)=>a+b,0))));el.querySelector('.node-queue').textContent=total;el.querySelector('small').textContent=walking?'WALK':clearance?'ALL RED':phase==='horizontal'?'EW':'NS'});$('sumoNote').style.display=state.topology==='german'?'flex':'none'}
function renderRoadUsers(bicycles,pedestrians){document.documentElement.style.setProperty('--ped-duration',`${3.4/state.speed}s`);document.querySelectorAll('.live-bike-count').forEach(el=>el.textContent=bicycles);document.querySelectorAll('.live-ped-count').forEach(el=>el.textContent=pedestrians);document.querySelectorAll('.vru-layer').forEach(layer=>{layer.querySelectorAll('.bike-rider').forEach((el,i)=>el.classList.toggle('visible',i<Math.min(4,bicycles)));layer.querySelectorAll('.ped-walker').forEach((el,i)=>el.classList.toggle('visible',i<Math.min(4,pedestrians)))})}
function render(){const nodes=activeNodes(),total=nodes.reduce((s,n)=>s+n.queues.reduce((a,b)=>a+b,0),0),bicycles=nodes.reduce((s,n)=>s+n.bicycles,0),pedestrians=nodes.reduce((s,n)=>s+n.pedestrians,0),vulnerable=bicycles+pedestrians,avg=state.arrived?state.delay/state.arrived:0,completion=state.arrived?state.processed/state.arrived*100:0,ns=nodes.reduce((s,n)=>s+n.queues[0]+n.queues[1],0),ew=nodes.reduce((s,n)=>s+n.queues[2]+n.queues[3],0),max=Math.max(ns,ew,1);$('totalQueue').textContent=total;$('avgWait').textContent=avg.toFixed(1);$('throughput').textContent=state.processed;$('completion').textContent=completion.toFixed(1);$('switchCount').textContent=state.switches;$('arrivalCount').textContent=`${state.arrived} arrivals · ${vulnerable} VRU`;$('simTime').textContent=formatTime(state.t);renderRoadUsers(bicycles,pedestrians);const gridMode=state.topology!=='single',germanMode=state.topology==='german';$('intersection').classList.toggle('is-hidden',gridMode);$('networkGrid').classList.toggle('is-hidden',!gridMode);$('environmentTitle').textContent=state.topology==='single'?'Multimodal four-way junction':germanMode?'Verified Lemgo road network':'Cooperative 2×2 district';if(gridMode)renderGrid();else renderSingle();const cyclePhase=signalPhase(),walking=cyclePhase==='pedestrian',clearance=cyclePhase==='clearance',yellow=nodes.some(n=>n.yellow),phase=walking?'PED CROSSING':clearance?'ALL RED':germanMode?'9 SIGNALS':gridMode?'4 AGENTS':cyclePhase==='horizontal'?'EW GREEN':'NS GREEN',clearanceRemaining=state.t%30===11||state.t%30===23?1:30-state.t%30;$('phaseBadge').querySelector('b').textContent=phase;$('phaseTimer').textContent=walking?`${28-state.t%30}s WALK`:clearance?`${clearanceRemaining}s CLEAR`:germanMode?'48 CONTROLLED LANES':gridMode?`${nodes.filter(n=>n.phase===0).length} NS · ${nodes.filter(n=>n.phase===1).length} EW`:`${nodes[0].age}s`;$('phaseBadge').querySelector('span').style.background=walking?'#d98cff':clearance?'var(--red)':yellow?'var(--amber)':'var(--green)';$('nsDemand').textContent=ns;$('ewDemand').textContent=ew;$('nsDemandBar').style.width=`${ns/max*100}%`;$('ewDemandBar').style.width=`${ew/max*100}%`;const conf=Math.min(96,Math.round(72+Math.abs(ns-ew)/(total||1)*22));$('confidence').textContent=`${conf}%`;$('decisionTitle').textContent=walking?'Protected pedestrian crossing':clearance?'Junction clearance':germanMode?'Native scenario verified':gridMode?'Four agents coordinating':yellow?'Safety transition':nodes[0].phase===0?'Hold north–south':'Hold east–west';$('decisionCopy').textContent=walking?`All vehicle and bicycle streams are stopped while ${pedestrians} pedestrians cross on marked crosswalks.`:clearance?'All road users are held at curb and stop lines until the intersection is empty.':germanMode?'SUMO 1.27.1 completed a 900-step TraCI run on central Lemgo OSM data with cars, bicycles, and pedestrians. This browser view is its lightweight interactive companion.':gridMode?`Local agents share network pressure; straight traffic transfers to neighboring queues. ${state.turns.left} left and ${state.turns.right} right turns completed.`:`The controller balances straight and turning traffic with ${vulnerable} cyclists/pedestrians waiting.`;const delta=state.lastQueue?((total-state.lastQueue)/state.lastQueue*100):0;$('queueTrend').textContent=`${delta<=0?'↓':'↑'} ${Math.abs(delta).toFixed(1)}%`;$('queueTrend').style.color=delta<=0?'var(--green)':'var(--red)';state.lastQueue=total;$('eventLog').innerHTML=state.events.length?state.events.map(e=>`<li><time>${formatTime(e.t)}</time><strong>${e.message}</strong></li>`).join(''):'<li><time>00:00</time><strong>Monitoring multimodal arrivals</strong></li>';drawChart()}
setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString('en-GB')},1000);setInterval(()=>{if(state.running){for(let i=0;i<state.speed;i++)step();render()}},500);
$('scenarioButtons').addEventListener('click',e=>{if(!e.target.dataset.scenario)return;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');state.scenario=e.target.dataset.scenario;reset();log(`Traffic profile · ${e.target.textContent}`);render()});$('topologySelect').addEventListener('change',e=>{state.topology=e.target.value;reset();log(`${e.target.options[e.target.selectedIndex].text} loaded`);render()});$('controllerSelect').addEventListener('change',e=>{state.controller=e.target.value;state.nodes.forEach(n=>n.fixedAge=0);log(`Controller · ${e.target.options[e.target.selectedIndex].text}`);render()});$('speedSelect').addEventListener('change',e=>state.speed=Number(e.target.value));$('playButton').addEventListener('click',()=>{state.running=!state.running;$('playButton').querySelector('span:last-child').textContent=state.running?'Pause run':'Resume run';$('playButton').querySelector('.pause-icon').textContent=state.running?'Ⅱ':'▶';$('runStatus').textContent=state.running?'SIMULATION LIVE':'SIMULATION PAUSED';document.querySelector('.pulse').style.background=state.running?'var(--green)':'var(--amber)'});$('resetButton').addEventListener('click',()=>reset());
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;context.registerTool({name:'configure_traffic_simulation',title:'Configure traffic simulation',description:'Set the visible network, traffic profile, controller, and speed, then reset the run.',inputSchema:{type:'object',properties:{topology:{type:'string',enum:['single','grid','german']},scenario:{type:'string',enum:['low','medium','heavy','unbalanced','rush']},controller:{type:'string',enum:['dqn','heuristic','fixed','random']},speed:{type:'number',enum:[1,2,5,10]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(input.topology){$('topologySelect').value=input.topology;state.topology=input.topology}if(input.scenario){state.scenario=input.scenario;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===input.scenario))}if(input.controller){$('controllerSelect').value=input.controller;state.controller=input.controller}if(input.speed){$('speedSelect').value=String(input.speed);state.speed=input.speed}reset();return{topology:state.topology,scenario:state.scenario,controller:state.controller,speed:state.speed,status:'configured'}}});context.registerTool({name:'read_traffic_metrics',title:'Read traffic metrics',description:'Read aggregate and per-agent queues, throughput, multimodal demand, and signal phases.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{topology:state.topology,timestep:state.t,agents:activeNodes().map((n,i)=>({id:'ABCD'[i],queues:n.queues,phase:n.yellow?'yellow':n.phase===0?'ns_green':'ew_green',pedestrians:n.pedestrians,bicycles:n.bicycles})),arrived:state.arrived,processed:state.processed,average_wait:state.arrived?Number((state.delay/state.arrived).toFixed(2)):0,switches:state.switches,turns:state.turns}}})}
reset(false);log('2×2 grid · cooperative RL demo active');render();registerTools();
